fields.InputDefinition:
{
  "goal": "Open the Chat application via the app switcher, wait for the workspace, and start a new conversation so the composer is focused. In the message composer, type an '@' character. Confirm a mention autocomplete popup appears listing selectable agents (names, possibly with icons). Optionally type a letter after '@' to see the list filter. Seeing the agent mention picker appear is success — you do NOT need to actually send a message. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
